const usd = (dollars: number) => `$${dollars.toFixed(2)}`;

async function describe(c: Ctx) {
  if (!c.available) {
    return `${c.name} server hosting${c.region ? ` in ${c.region.label}` : ""} on Nxeon: not available to order right now. Contact us about ${c.name} hosting, or see the ${c.games.length} games you can deploy today.`;
  }
  const from = usd(Math.min(...c.tiers.map(priceOf)));
  const slots = c.tiers.map((x) => x.slots).filter((s): s is number => s != null);
  const size = `${c.tiers.length} plan${c.tiers.length === 1 ? "" : "s"} from ${c.tiers[0].ram} to ${c.topT.ram} GB${slots.length ? `, recommended for up to ${Math.max(...slots)} players` : ""}`;
  return c.region
    ? `${c.name} servers in ${c.region.label} from ${from}/mo: ${size}, five-layer DDoS protection and full file access. Live in about a minute.`
    : `${c.name} server hosting from ${from}/mo: ${size}, servers in ${list(c.regions.map((r) => r.label))}, five-layer DDoS protection and full file access.`;
}

export async function gameMeta(p: Record<string, string>, loc: boolean) {
  const c = await context(p.family, loc ? p.region : null);
  const art = gameArt(c.family);
  const r = c.region;
  return {
    title: r ? `${c.name} Server Hosting in ${r.label}` : c.available ? `${c.name} Server Hosting — Instant Setup, From ${usd(Math.min(...c.tiers.map(priceOf)))}/mo` : `${c.name} Server Hosting`,
    description: await describe(c),
    crumb: r ? r.label : `${c.name} server hosting`,
    ...(art.hero ? { image: art.hero } : {}),
  };
}

