/**
 * The game template (/minecraft-server-hosting fanned out to every sellable
 * game) and the game x location template (/<game>/<region>), both from the
 * design's build_gs2.py page, filled per request from the system:
 *
 * - tiers: db.gamePlan (RAM, vCPU, NVMe, slots, price, intro) — what checkout sells
 * - regions: enabled db.node rows (+ lib/node-regions.ts labels)
 * - server types + versions: lib/game-config.ts (the deploy wizard's own schema)
 * - mods: NxLabs catalogue (lib/mods-catalog.ts); "one click" only where
 *   lib/mod-install-support.ts can really install for the game
 * - sizing: lib/game-player-recommend.ts (the wizard's per-game curve)
 * - backups: lib/backup-tiers.ts; free tier: Settings (free_minecraft_enabled)
 *
 * Fails closed: an unknown game, a game with no active plans or a region with
 * no enabled node is a 404, never a snapshot.
 */

/** OPEN-ITEM (heuristic, not system data): how much a mod pack multiplies the
 *  game's vanilla memory need in the "Will it fit?" meter. Shown only for
 *  games with NxLabs mods. The vanilla baseline itself is the system's curve. */
const PACK: Record<string, [number, string]> = { vanilla: [1, "Vanilla"], light: [1.25, "Light mods"], modpack: [1.75, "Modpack"], heavy: [2.5, "Heavy pack"] };

const I = (n: string) => `<span data-au-icon="${n}" data-grad></span>`;
const cap = (s: string) => s.charAt(0).toUpperCase() + s.slice(1);
const list = (xs: string[]) => (xs.length <= 1 ? xs.join("") : `${xs.slice(0, -1).join(", ")} and ${xs[xs.length - 1]}`);
const orList = (xs: string[]) => (xs.length <= 1 ? xs.join("") : `${xs.slice(0, -1).join(", ")} or ${xs[xs.length - 1]}`);
const priceOf = (t: RealTier) => t.i ?? t.p;

async function context(family: string, regionCode: string | null) {
  if (!isGameFamily(family)) notFound();
  const route = gameRoute(family);
  if (!route) notFound();
  const regions = await deployRegions();
  if (!regions.length) throw new Error("nxm games: no enabled nodes");
  const region = regionCode ? regions.find((r) => r.code === regionCode) : null;
  if (regionCode && !region) notFound();
  if (region && !region.info) throw new Error(`nxm games: no REGION_INFO for ${region.code}`);
  const tiers = await realTiers(family, regions.map((r) => r.code));
  /* no active plans right now: the page stays (content, SEO), ordering UI goes */
  const available = tiers.length > 0;

  const name = gameName(family);
  const schema = schemaFor(family);
  const variants = schema && schema.variants.length > 1 ? schema.variants : [];
  const verField = schema?.fields.find((f) => f.key === "VERSION" && f.type === "enum" && f.options?.length);
  const curve = GAME_PLAYER_CURVES[family as GameFamily];
  if (!curve) throw new Error(`nxm games: no sizing curve for ${family}`);

  const [families, top] = await Promise.all([listCatalogFamilies(), listTopDownloadedMods(family, 12)]);
  const modCount = families.find((f) => f.family === family)?.count ?? 0;
  let mods: ModSummary[] = top;
  const ranked = top.length > 0;
  if (!mods.length && modCount) mods = (await queryCatalogMods({ family, sort: "featured", perPage: 10 })).mods;
  mods = mods.slice(0, 10);
  const oneClick = INSTALLABLE_FAMILIES.has(family);
  const consoleMods = oneClick ? mods.filter((m) => installSupport(family, m.source).ok).slice(0, 3) : [];
  const freeMc = family === "minecraft" && (await getSettingBool("free_minecraft_enabled", false));
  // An admin-run free community server for this game (FreePublicServer, LIVE only) — null otherwise.
  const freeCommunity = (await listVisibleFreePublicServers(family))[0] ?? null;
  const games = await sellableGames();

  const withMods = modCount > 0;
  const pack = withMods ? PACK : null;
  const need = (pl: number, pk: string | null) => ((curve.ramBaseMB + curve.ramPerPlayerMB * pl) / 1024) * (pk ? PACK[pk][0] : 1);
  const fitsAt = (t: RealTier, pl: number, pk: string | null) => (t.slots == null || t.slots >= pl) && (!pk || pk === "vanilla" || t.ram >= need(pl, pk));
  const recFor = (pl: number, pk: string | null) => { const i = tiers.findIndex((t) => fitsAt(t, pl, pk)); return i < 0 ? tiers.length - 1 : i; };
  const topT = tiers[tiers.length - 1] as RealTier; // undefined when !available (never read then)
  const maxPlayers = topT?.slots ?? curve.maxSeededSlots;
  const players = Math.min(10, tiers[0]?.slots ?? 10, maxPlayers);
  const def = available ? recFor(players, pack ? (variants.length && schema?.defaultVariant === "vanilla" ? "vanilla" : consoleMods.length ? "light" : "vanilla") : null) : 0;
  const R = region ?? regions[0];

  return {
    family, name, route, regions, region, R, tiers, schema, variants, verField, curve, mods, ranked, modCount, oneClick, consoleMods,
    freeMc, freeCommunity, games, withMods, pack, def, players, maxPlayers, topT, world: worldWord(family), available,
  };
}
type Ctx = Awaited<ReturnType<typeof context>>;

