/**
 * SEO audit worker hook. One call per worker loop iteration:
 *   1. picks up an admin "run audit now" request (a SeoAuditRun row with status
 *      QUEUED, created by lib/actions-seo-audit.ts) and runs it;
 *   2. otherwise starts the weekly scheduled audit if one is due.
 * Read-only against our own public site (plain GETs + a few headless-Chromium
 * page loads); writes only SeoAuditRun/SeoAuditPage rows and, on a score drop,
 * an in-app admin Notification. Kill-switch: Setting `seo_audit_enabled`.
 */
import { db } from "../lib/db";
import { getSettingBool } from "../lib/settings";
import { runAndPersistAudit } from "../lib/seo-audit/persist";
import { notifyAdmins } from "./monitor";

let lastCheck = 0;
let running = false;
const WEEK = 7 * 24 * 60 * 60_000;

export function seoAuditBaseUrl(): string {
  return (process.env.SEO_AUDIT_BASE_URL ?? process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");
}

export async function seoAuditTick(): Promise<void> {
  if (running || Date.now() - lastCheck < 60_000) return;
  lastCheck = Date.now();
  running = true;
  try {
    // Orphaned RUNNING rows (worker restarted mid-audit) would block the schedule forever.
    await db.seoAuditRun.updateMany({ where: { status: "RUNNING", startedAt: { lt: new Date(Date.now() - 60 * 60_000) } }, data: { status: "FAILED", error: "worker restarted mid-run", finishedAt: new Date() } });

    const queued = await db.seoAuditRun.findFirst({ where: { status: "QUEUED" }, orderBy: { startedAt: "asc" } });
    let runId = queued?.id;
    let trigger: "manual" | "weekly" = "manual";
    if (!queued) {
      if (!(await getSettingBool("seo_audit_enabled", true))) return;
      const last = await db.seoAuditRun.findFirst({ where: { trigger: "weekly" }, orderBy: { startedAt: "desc" } });
      if (last && Date.now() - last.startedAt.getTime() < WEEK) return;
      trigger = "weekly";
    }
    const baseUrl = queued?.baseUrl ?? seoAuditBaseUrl();
    const { regressions, result } = await runAndPersistAudit(
      // modest fan-out: this runs against production's own web process
      { baseUrl, perTemplate: 25, maxPages: 500, concurrency: 3, speedSample: 8, linkCheckLimit: 150 },
      trigger,
      runId,
    );
    console.log(`[seo-audit] ${trigger} run done: score ${result.avgScore}, ${result.pages.length} pages, ${regressions.length} regressions`);
    if (regressions.length) {
      await notifyAdmins(
        "SEO score dropped",
        regressions.map((r) => `${r.name}: ${r.previous} → ${r.current}`).join("; "),
        "/admin/seo/audit",
      );
    }
  } catch (e) {
    console.error("[seo-audit] run error", e);
  } finally {
    running = false;
  }
}
