/**
 * IndexNow transport, importable from the worker and scripts (no "server-only").
 * lib/indexnow.ts re-exports these for app code. Every function here is best-effort
 * and never throws: an indexing ping must never break the caller.
 *
 * Ownership is proven by the public key file at `${APP_URL}/${KEY}.txt` (public/).
 */
export const INDEXNOW_KEY = process.env.INDEXNOW_KEY || "16a2ca6a7f858b5636722410f29b2117";
export const INDEXNOW_ENDPOINT = "https://api.indexnow.org/indexnow";
/** IndexNow accepts at most 10,000 URLs per request. */
export const INDEXNOW_MAX_BATCH = 10_000;

const APP_URL = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");
const HOST = APP_URL.replace(/^https?:\/\//, "");

/** Absolute, deduplicated, same-host URLs only (IndexNow rejects foreign hosts). */
export function normalizeIndexNowUrls(urls: string[], appUrl = APP_URL): string[] {
  return Array.from(
    new Set(
      urls
        .map((u) => (u.startsWith("http") ? u : `${appUrl}${u.startsWith("/") ? "" : "/"}${u}`))
        .filter((u) => u.startsWith(appUrl)),
    ),
  );
}

/** One POST for up to 10,000 URLs. Reports whether the endpoint accepted it (200/202). */
export async function submitIndexNow(urls: string[]): Promise<{ ok: boolean; status: number; sent: number }> {
  try {
    const list = normalizeIndexNowUrls(urls).slice(0, INDEXNOW_MAX_BATCH);
    if (!list.length) return { ok: true, status: 0, sent: 0 };
    const res = await fetch(INDEXNOW_ENDPOINT, {
      method: "POST",
      headers: { "content-type": "application/json; charset=utf-8" },
      body: JSON.stringify({ host: HOST, key: INDEXNOW_KEY, keyLocation: `${APP_URL}/${INDEXNOW_KEY}.txt`, urlList: list }),
    });
    return { ok: res.status === 200 || res.status === 202, status: res.status, sent: list.length };
  } catch {
    return { ok: false, status: -1, sent: 0 };
  }
}
