/** Pure planning for the IndexNow sweep (no db / network, unit-tested). */

export interface SweepEntry { url: string; fingerprint: string }

/** Fingerprint of a sitemap entry: its lastmod ISO, "" when the page has none. */
export const fingerprintOf = (lastModified?: Date | null): string => (lastModified ? lastModified.toISOString() : "");

/**
 * URLs to announce this run: never seen before, or whose fingerprint moved.
 * Unchanged URLs are never re-sent (IndexNow asks for changed URLs only). Newest
 * lastmod first so fresh content wins when a run is capped; `limit` bounds a run
 * (the first run after enabling would otherwise be the whole catalogue).
 */
export function planSweep(current: SweepEntry[], known: Map<string, string>, limit: number): { toSend: SweepEntry[]; pending: number } {
  const changed = current.filter((e) => known.get(e.url) !== e.fingerprint);
  changed.sort((a, b) => (a.fingerprint < b.fingerprint ? 1 : a.fingerprint > b.fingerprint ? -1 : 0));
  return { toSend: changed.slice(0, Math.max(0, limit)), pending: Math.max(0, changed.length - Math.max(0, limit)) };
}

export function chunk<T>(xs: T[], n: number): T[][] {
  const out: T[][] = [];
  for (let i = 0; i < xs.length; i += n) out.push(xs.slice(i, i + n));
  return out;
}
