cat > lib/indexnow-sweep.ts <<'E'
/**
 * IndexNow sweep (seo-002). Walks every sitemap section (core, games, game-locations,
 * locations, compare, tools, blog, servers, mods-N) and announces to IndexNow only the
 * URLs that are new or whose <lastmod> moved since the last accepted submission, so
 * Bing (which feeds ChatGPT search) hears about landing, game, tool, location and mod
 * pages, not just blog posts.
 *
 * SAFETY: default OFF. The worker tick does nothing unless Setting
 * `indexnow_sweep_enabled` is true. `dryRun` plans without sending or recording.
 * Nothing is recorded as submitted unless the endpoint answered 200/202, so a failed
 * run is simply retried. Imports no "server-only" module (the worker runs under tsx).
 */
import { db } from "./db";
import { getSettingBool, getSettingInt } from "./settings";
import { listSections, sectionEntries } from "./sitemap-sections";
import { INDEXNOW_MAX_BATCH, submitIndexNow } from "./indexnow-core";
import { chunk, fingerprintOf, planSweep, type SweepEntry } from "./indexnow-sweep-pure";

export interface SweepResult { enabled: boolean; considered: number; planned: number; sent: number; pending: number; dryRun: boolean; errors: string[] }

export async function collectSitemapEntries(): Promise<SweepEntry[]> {
  const out = new Map<string, SweepEntry>();
  for (const s of await listSections()) {
    for (const e of await sectionEntries(s.id)) out.set(e.url, { url: e.url, fingerprint: fingerprintOf(e.lastModified) });
  }
  return [...out.values()];
}

export async function runIndexNowSweep(opts: { dryRun?: boolean; force?: boolean; limit?: number } = {}): Promise<SweepResult> {
  const dryRun = !!opts.dryRun;
  const enabled = await getSettingBool("indexnow_sweep_enabled", false);
  const res: SweepResult = { enabled, considered: 0, planned: 0, sent: 0, pending: 0, dryRun, errors: [] };
  if (!enabled && !opts.force) return res;
  const limit = opts.limit ?? Math.min(await getSettingInt("indexnow_sweep_max_per_run", 2000), INDEXNOW_MAX_BATCH * 5);
  const current = await collectSitemapEntries();
  res.considered = current.length;
  const rows = await db.indexNowUrl.findMany({ select: { url: true, fingerprint: true } });
  const known = new Map(rows.map((r) => [r.url, r.fingerprint]));
  const { toSend, pending } = planSweep(current, known, limit);
  res.planned = toSend.length;
  res.pending = pending;
  if (dryRun) return res;
  for (const batch of chunk(toSend, INDEXNOW_MAX_BATCH)) {
    const r = await submitIndexNow(batch.map((b) => b.url));
    if (!r.ok) { res.errors.push(`IndexNow answered ${r.status}`); break; }
    res.sent += r.sent;
    await db.$transaction(batch.map((b) => db.indexNowUrl.upsert({ where: { url: b.url }, create: { url: b.url, fingerprint: b.fingerprint }, update: { fingerprint: b.fingerprint, submittedAt: new Date() } })));
  }
  return res;
}
