/**
 * IndexNow sweep hook (seo-002). Self-throttled to one run per 6 hours; does nothing unless the
 * Setting `indexnow_sweep_enabled` is true (default OFF — it sends URLs to a public search-engine
 * API). See lib/indexnow-sweep.ts.
 */
import { runIndexNowSweep } from "../lib/indexnow-sweep";

let lastRun = 0;
let running = false;
const EVERY = 6 * 60 * 60_000;

export async function indexNowTick(): Promise<void> {
  if (running || Date.now() - lastRun < EVERY) return;
  running = true;
  try {
    const r = await runIndexNowSweep();
    if (r.enabled) {
      lastRun = Date.now();
      console.log(`[indexnow] considered ${r.considered}, sent ${r.sent}, pending ${r.pending}${r.errors.length ? `, errors: ${r.errors.join("; ")}` : ""}`);
    } else {
      lastRun = Date.now() - EVERY + 10 * 60_000; // disabled: re-check the flag every 10 min
    }
  } catch (e) {
    console.error("[indexnow] sweep error", e);
  } finally {
    running = false;
  }
}
