/** A production route, pointed inside the staged new site when that route has
 *  been ported (its app/nxm page exists), otherwise at the live page. At
 *  launch NXM_BASE is "" and this is the identity. */
const portedCache = new Map<string, boolean>();
export function stagedHref(href: string): string {
  const m = href.match(/^(\/[^?#]*)(.*)$/);
  if (!m || !NXM_BASE) return href;
  const [, route, rest] = m;
  let ported = portedCache.get(route);
  if (ported === undefined) {
    ported = fs.existsSync(path.join(process.cwd(), "app/nxm", route === "/" ? "" : route, "page.tsx"));
    portedCache.set(route, ported);
  }
  return ported ? NXM_BASE + (route === "/" ? "" : route) + rest : href;
}

// ── React output -> HTML (fail closed) ─────────────────────────────────────
const TAGS = new Set(["p", "ul", "ol", "li", "b", "strong", "i", "em", "code", "br", "span", "div", "a", "h2", "h3", "small"]);
type El = ReactElement<Record<string, unknown> & { children?: ReactNode }>;
const kids = (n: ReactNode): ReactNode[] => (Array.isArray(n) ? n.flatMap((x) => kids(x as ReactNode)) : n == null ? [] : [n]);

export function toHtml(node: ReactNode): string {
  if (node == null || typeof node === "boolean") return "";
  if (typeof node === "string" || typeof node === "number") return esc(String(node));
  if (Array.isArray(node)) return node.map(toHtml).join("");
  if (!isValidElement(node)) throw new Error("nxm tools: unsupported node in live tool content");
  const el = node as El;
  const inner = toHtml(el.props.children as ReactNode);
  if (el.type === Fragment) return inner;
  const href = typeof el.props.href === "string" ? el.props.href : null;
  if (typeof el.type === "string") {
    if (!TAGS.has(el.type)) throw new Error(`nxm tools: <${el.type}> in live tool content`);
    if (el.type === "br") return "<br>";
    if (el.type === "a") return `<a href="${esc(stagedHref(href ?? "#"))}"${el.props.target ? ` target="_blank" rel="noopener noreferrer"` : ""}>${inner}</a>`;
    return `<${el.type}>${inner}</${el.type}>`;
  }
  // next/link (a client reference on the server): any component with an href
  if (href) return `<a href="${esc(stagedHref(href))}">${inner}</a>`;
  throw new Error("nxm tools: unsupported component in live tool content");
}

/** Plain text of a node (headings). */
export function toText(node: ReactNode): string {
  return toHtml(node).replace(/<[^>]+>/g, "").replace(/&#39;/g, "'").replace(/&#34;/g, '"').replace(/&#38;/g, "&").replace(/&#60;/g, "<").replace(/&#62;/g, ">").trim();
}

/** Depth-first walk over a live page's element tree (through components'
 *  children props — nothing is rendered). */
function walk(node: ReactNode, visit: (el: El, parent: El | null) => void, parent: El | null = null) {
  for (const n of kids(node)) {
    if (!isValidElement(n)) continue;
    const el = n as El;
    visit(el, parent);
    walk(el.props.children as ReactNode, visit, el);
  }
}

