import { PrismaClient, Prisma } from "@prisma/client";
import { modBarSql } from "../lib/mod-quality";

const db = new PrismaClient();
(async () => {
  const floor = Number(process.env.SEO_MOD_NOINDEX_BELOW ?? 100);
  const base = Prisma.sql`"active" AND "upstreamOk" AND "duplicateOfId" IS NULL`;
  const [{ total }] = await db.$queryRaw<{ total: number }[]>(Prisma.sql`SELECT count(*)::int AS total FROM "GameMod" WHERE ${base}`);
  const [{ pass }] = await db.$queryRaw<{ pass: number }[]>(Prisma.sql`SELECT count(*)::int AS pass FROM "GameMod" WHERE ${base} AND ${modBarSql(floor)}`);
  const byFamily = await db.$queryRaw<{ gameFamily: string; total: number; pass: number }[]>(
    Prisma.sql`SELECT "gameFamily", count(*)::int AS total, count(*) FILTER (WHERE ${modBarSql(floor)})::int AS pass FROM "GameMod" WHERE ${base} GROUP BY 1 ORDER BY 2 DESC`,
  );
  console.log(JSON.stringify({ floor, total, pass, noindexed: total - pass, byFamily }, null, 1));
  await db.$disconnect();
})();
