import test from "node:test";
import assert from "node:assert/strict";
import { modBarFailures, installablePairs, modBarSql, type ModQualityInput } from "../lib/mod-quality";
import { installSupport } from "../lib/mod-install-support";
import { planSweep, fingerprintOf, chunk } from "../lib/indexnow-sweep-pure";
import { normalizeIndexNowUrls } from "../lib/indexnow-core";

const good: ModQualityInput = {
  gameFamily: "minecraft", source: "modrinth", downloads: 5000,
  description: "x".repeat(320), longDescription: null, impactNote: null,
  loaders: ["fabric"], gameVersions: ["1.21.1"], serverSide: "required", verifiedAt: new Date(),
};

test("a mod that clears every rule passes", () => assert.deepEqual(modBarFailures(good, 100), []));

test("each rule fails on its own", () => {
  assert.deepEqual(modBarFailures({ ...good, downloads: 12 }, 100), ["downloads"]);
  assert.deepEqual(modBarFailures({ ...good, downloads: null }, 0), ["downloads"]);
  assert.deepEqual(modBarFailures({ ...good, description: "short" }, 100), ["words"]);
  assert.deepEqual(modBarFailures({ ...good, description: "short", impactNote: "Heavy on chunk loading." }, 100), []);
  assert.deepEqual(modBarFailures({ ...good, description: "short", longDescription: "y".repeat(400) }, 100), []);
  assert.deepEqual(modBarFailures({ ...good, loaders: [] }, 100), ["compat"]);
  assert.deepEqual(modBarFailures({ ...good, gameVersions: [] }, 100), ["compat"]);
  assert.deepEqual(modBarFailures({ ...good, serverSide: "unsupported" }, 100), ["compat"]);
  assert.deepEqual(modBarFailures({ ...good, verifiedAt: null }, 100), ["dependencies"]);
  assert.deepEqual(modBarFailures({ ...good, source: "curseforge" }, 100), ["install"]);
});

test("non-minecraft games need a declared server-side status", () => {
  const v: ModQualityInput = { ...good, gameFamily: "valheim", source: "thunderstore", loaders: [], gameVersions: [] };
  assert.deepEqual(modBarFailures({ ...v, serverSide: "optional" }, 100), []);
  assert.deepEqual(modBarFailures({ ...v, serverSide: null }, 100), ["compat"]);
});

test("SQL install pairs are exactly the pairs installSupport() accepts", () => {
  const pairs = installablePairs();
  assert.ok(pairs.length > 10);
  for (const [f, s] of pairs) assert.equal(installSupport(f, s).ok, true, `${f}/${s}`);
  assert.ok(pairs.some(([f, s]) => f === "valheim" && s === "thunderstore"));
  assert.ok(!pairs.some(([f, s]) => f === "minecraft" && s === "curseforge"));
  assert.ok(modBarSql(100).sql.includes("char_length"));
});

