function fmtPrice(cents: number): string {
  return `$${(cents / 100).toFixed(2)}`;
}

const GROUPS: Workload["group"][] = ["Game servers", "Web & apps", "Bots & self-hosting"];

export function ServerSizeCalculatorTool({ plans }: { plans: PlanSpec[] }) {
  const [workloadId, setWorkloadId] = useState(WORKLOADS[0].id);
  const workload = WORKLOADS.find((w) => w.id === workloadId) ?? WORKLOADS[0];
  const [scale, setScale] = useState<number>(workload.scaleDefault ?? 10);

  function pickWorkload(id: string) {
    const w = WORKLOADS.find((x) => x.id === id) ?? WORKLOADS[0];
    setWorkloadId(id);
    setScale(w.scaleDefault ?? 10);
  }

  const rec = useMemo(() => recommendPlan(workload, scale, plans), [workload, scale, plans]);

  return (
    <div className="space-y-5">
      <div className="grid gap-4 sm:grid-cols-2">
        <Field label="What are you hosting?">
          <select className="input" value={workloadId} onChange={(e) => pickWorkload(e.target.value)}>
            {GROUPS.map((g) => (
              <optgroup key={g} label={g}>
                {WORKLOADS.filter((w) => w.group === g).map((w) => (
                  <option key={w.id} value={w.id}>
                    {w.label}
                  </option>
                ))}
              </optgroup>
            ))}
          </select>
        </Field>

        {workload.scale !== "none" ? (
          <Field label={workload.scaleLabel ?? "Scale"}>
            <input
              className="input"
              type="range"
              min={1}
              max={workload.scaleMax ?? 100}
              value={scale}
              onChange={(e) => setScale(Number(e.target.value))}
            />
            <span className="mt-1 block text-xs text-slate-400">
                website — into a concrete <b>RAM, CPU and storage</b> recommendation, then maps it to
                the smallest Nxeon plan that comfortably fits, with the real monthly price.
              </p>
            ),
          },
          {
            heading: "Covers games, web apps and self-hosting",
            body: (
              <ul className="list-disc space-y-1 pl-5">
                <li><b>Game servers</b> — Minecraft, Rust, Palworld, Valheim, ARK, FiveM, CS2 and more.</li>
                <li><b>Web & apps</b> — websites, WordPress, Node.js backends, Docker stacks.</li>
                <li><b>Bots & self-hosting</b> — Discord bots, Nextcloud, WireGuard VPN.</li>
              </ul>
            ),
          },
        ]}
        steps={[
          "Choose what you're hosting from the list.",
          "Set your scale — player count or monthly traffic.",
          "Read the recommended RAM, CPU and storage.",
          "See the matching Nxeon plan and price, and jump straight to it.",
        ]}
        faq={faq}
        related={relatedTools("server-size-calculator")}
      >
        <ServerSizeCalculatorTool plans={rows} />
      </ToolShell>
    </>
  );
}
