const CATEGORY_LABEL: Record<ToolCategory, string> = { Network: "Network tool", Developer: "Developer tool", Security: "Security tool", Servers: "Server tool" };
// schema.org applicationCategory, exactly as the live ToolShell maps it
const APPLICATION_CATEGORY: Record<ToolCategory, string> = {
  Network: "UtilitiesApplication", Developer: "DeveloperApplication", Security: "SecurityApplication", Servers: "UtilitiesApplication",
};
const slugOfHref = (href: string) => href.replace(/^\/tools\//, "").replace(/[?#].*$/, "");

export async function toolContent(slug: string): Promise<ToolContent | null> {
  const tool = catalogTool(slug);
  const load = LIVE[slug];
  if (!tool || !load || slug.startsWith("__")) return null;
  const mod = await load();
  const metaTitle = typeof mod.metadata.title === "string" ? mod.metadata.title : null;
  const metaDescription = mod.metadata.description ?? null;
  if (!metaTitle || !metaDescription) throw new Error(`nxm tools: live /tools/${slug} has no title/description`);
  const tree = await mod.default();

  let shell: El | null = null;
  walk(tree, (el) => { if (el.type === ToolShell) shell = el; });
  if (shell) {
    const p = (shell as El).props as unknown as {
      category: string; title: string; description: string;
      about?: { heading: string; body: ReactNode }[]; steps?: string[]; faq?: { q: string; a: string }[]; related?: { href: string }[];
      jsonLd?: Record<string, unknown>[]; cta?: ToolContent["cta"]; facts?: string[];
    };
    // the live ToolShell's WebApplication entity, field for field — unless the
    // page supplies its own app entity (ToolShell drops the default then too)
    const ownLd = p.jsonLd ?? [];
    const ownApp = ownLd.some((e) => e["@type"] === "SoftwareApplication" || e["@type"] === "WebApplication");
    const appLd = ownApp ? [] : [{
      "@context": "https://schema.org", "@type": "WebApplication",
      name: tool.name, description: p.description, url: `${APP_URL}/tools/${slug}`,
      applicationCategory: APPLICATION_CATEGORY[tool.category], operatingSystem: "Any (web browser)",
      offers: { "@type": "Offer", price: "0", priceCurrency: "USD" }, isAccessibleForFree: true,
    }];
    return {
      slug, tool, metaTitle, metaDescription,
      category: p.category, title: p.title, crumb: p.title, description: p.description,
      about: (p.about ?? []).map((b) => ({ heading: b.heading, html: toHtml(b.body) })),
      steps: (p.steps ?? []).map((s) => ({ body: s })),
      faq: p.faq ?? [],
      related: (p.related ?? relatedTools(slug)).map((r) => slugOfHref(r.href)),
      jsonLd: [...appLd, ...ownLd],
      cta: p.cta,
      facts: p.facts,
    };
  }

  // A bespoke live landing (Minecraft status): explainer blocks are the
  // <div>s holding an <h2>; FAQ + SoftwareApplication come from its own JSON-LD.
  const about: { heading: string; html: string }[] = [];
  const ld: Record<string, unknown>[] = [];
  walk(tree, (el) => {
    if (el.type === "script") {
      const raw = (el.props.dangerouslySetInnerHTML as { __html?: string } | undefined)?.__html;
      if (raw) ld.push(JSON.parse(raw));
      return;
    }
    if (el.type !== "div") return;
    const ch = kids(el.props.children as ReactNode).filter(isValidElement) as El[];
    if (ch[0]?.type === "h2") about.push({ heading: toText(ch[0].props.children as ReactNode), html: ch.slice(1).map(toHtml).join("") });
  });
  const faqLd = ld.find((b) => b["@type"] === "FAQPage") as { mainEntity: { name: string; acceptedAnswer: { text: string } }[] } | undefined;
