"use client";

import Link from "next/link";
import { useMemo, useState } from "react";
import { CodeOutput, Field, ResultCard } from "./ui";
import {
  PALWORLD_FIELDS, VALHEIM_FIELDS, cleanValue, defaultsOf, palworldEnv, palworldIni, valheimArgs, valheimOverridden,
  type GenField, type GenValues,
} from "@/lib/tools/config-generators";

/** One form for both generators (seo-018); the generators' rules live in lib/tools/config-generators.ts. */
export function GameConfigGeneratorTool({ kind }: { kind: "palworld" | "valheim" }) {
  const fields: GenField[] = kind === "palworld" ? PALWORLD_FIELDS : VALHEIM_FIELDS;
  const [values, setValues] = useState<GenValues>(() => defaultsOf(fields));
  const [basics, setBasics] = useState({ name: "My Valheim Server", world: "Dedicated", password: "", port: 2456, crossplay: false });
  const set = (f: GenField, raw: unknown) => setValues((v) => ({ ...v, [f.id]: cleanValue(f, raw) }));

  const groups = useMemo(() => [...new Set(fields.map((f) => f.group))], [fields]);
  const overridden = kind === "valheim" ? valheimOverridden(values) : [];
  const home = kind === "palworld" ? "/palworld-server-hosting" : "/valheim-server-hosting";

  return (
    <div className="space-y-5">
      {kind === "valheim" && (
        <div className="grid gap-4 sm:grid-cols-2">
          <Field label="Server name"><input className="input" value={basics.name} maxLength={64} onChange={(e) => setBasics({ ...basics, name: e.target.value })} /></Field>
          <Field label="World name"><input className="input" value={basics.world} maxLength={40} onChange={(e) => setBasics({ ...basics, world: e.target.value })} /></Field>
          <Field label="Server password" hint="At least 5 characters, and not part of the world name. Placeholder used if blank."><input className="input" value={basics.password} onChange={(e) => setBasics({ ...basics, password: e.target.value })} /></Field>
          <Field label="Crossplay"><label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={basics.crossplay} onChange={(e) => setBasics({ ...basics, crossplay: e.target.checked })} /> Allow Xbox / Game Pass players</label></Field>
        </div>
      )}
      {groups.map((g) => (
        <div key={g}>
          <p className="section-label mb-2">{g}</p>
          <div className="grid gap-4 sm:grid-cols-2">
            {fields.filter((f) => f.group === g).map((f) => (
              <Field key={f.id} label={f.label} hint={f.help}>
                {f.type === "enum" ? (
                  <select className="input" value={String(values[f.id])} onChange={(e) => set(f, e.target.value)}>
                    {f.options.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}
                  </select>
                ) : f.type === "int" ? (
                  <input className="input" type="number" min={f.min} max={f.max} value={Number(values[f.id])} onChange={(e) => set(f, e.target.value)} />
                ) : (
                  <label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={values[f.id] === true} onChange={(e) => set(f, e.target.checked)} /> Enabled</label>
                )}
              </Field>
            ))}
          </div>
        </div>
      ))}

      {overridden.length > 0 && (
        <p className="text-sm text-amber-300">A preset overrides individual modifiers, so the game will ignore: {overridden.join(", ")}. Set the preset to Normal to use them.</p>
      )}

      {kind === "palworld" ? (
        <>
          <ResultCard title="PalWorldSettings.ini">
            <CodeOutput text={palworldIni(values)} />
            <p className="mt-2 text-xs text-slate-400">Linux path: Pal/Saved/Config/LinuxServer/PalWorldSettings.ini. Stop the server before editing; keys you do not list keep the game&apos;s defaults. This covers the options Nxeon&apos;s own settings panel manages.</p>
          </ResultCard>
          <ResultCard title="Docker environment (thijsvanloef/palworld-server-docker)">
            <CodeOutput text={palworldEnv(values)} />
          </ResultCard>
        </>
      ) : (
        <ResultCard title="Launch arguments">
          <CodeOutput text={valheimArgs(values, basics)} />
          <p className="mt-2 text-xs text-slate-400">Append these to your valheim_server start command. Only modifiers that differ from Normal are emitted.</p>
        </ResultCard>
      )}

      <p className="text-sm text-slate-300">
        Want it running? <Link className="underline" href={home}>Deploy a {kind === "palworld" ? "Palworld" : "Valheim"} server on Nxeon</Link> and set the same options in the deploy wizard&apos;s Settings, or edit them later from your server&apos;s Settings tab.
      </p>
    </div>
  );
}
