import type { Metadata } from "next";
import { ToolShell, FaqJsonLd, type ToolFaq } from "@/components/marketing/ToolShell";
import { HashGeneratorTool } from "@/components/marketing/tools/HashGeneratorTool";
import { relatedTools } from "@/lib/tools/catalog";

export const metadata: Metadata = {
  title: "Free Hash Generator — SHA-1, SHA-256, SHA-384, SHA-512",
  description:
    "Free online hash generator. Compute SHA-1, SHA-256, SHA-384 and SHA-512 hashes of any text instantly in your browser with the Web Crypto API. Nothing is uploaded.",
  alternates: { canonical: "/tools/hash-generator" },
};

const faq: ToolFaq[] = [
  {
    q: "What is a cryptographic hash?",
    a: "A hash function turns any input into a fixed-length string (the digest). The same input always yields the same digest, and it's infeasible to reverse the digest back to the input or to find two inputs with the same digest. Hashes are used for integrity checks, fingerprints and password storage schemes.",
  },
  {
    q: "Which hash algorithm should I use?",
    a: "Use SHA-256 or stronger for new work. SHA-1 is included for compatibility and verifying legacy values but is considered broken for security purposes and should not be used to protect anything.",
  },
  {
    q: "Why isn't MD5 included?",
    a: "MD5 is cryptographically broken — collisions are trivial to produce — and the Web Crypto API deliberately doesn't offer it. We omit it to steer you toward secure algorithms. SHA-256 is the modern default.",
  },
  {
    q: "Is my input sent to a server?",
    a: "No. Hashing is done entirely in your browser with crypto.subtle. The text you enter never leaves your device.",
  },
];

export default function Page() {
  return (
    <>
      <FaqJsonLd faq={faq} />
      <ToolShell
        slug="hash-generator"
        category="Security tool"
        title="Hash Generator"
        description="Compute SHA-1, SHA-256, SHA-384 and SHA-512 digests of any text instantly. Hashed locally in your browser — your input is never uploaded."
        about={[
          {
            heading: "What is a hash generator?",
            body: (
              <p>
                A hash generator computes the cryptographic digest of your input — a fixed-length
                fingerprint that changes completely if even one character changes. Developers use hashes to
                verify file integrity, generate cache keys and content fingerprints, compare values without
                storing the originals, and check downloads against a published checksum. This tool computes
                four SHA-family digests at once using the browser's Web Crypto API.

