import type { Metadata } from "next";
import { ToolShell, FaqJsonLd, type ToolFaq } from "@/components/marketing/ToolShell";
import { GameConfigGeneratorTool } from "@/components/marketing/tools/GameConfigGeneratorTool";
import { relatedTools } from "@/lib/tools/catalog";

export const metadata: Metadata = {
  title: "Palworld Server Settings Generator — PalWorldSettings.ini",
  description:
    "Free Palworld server settings generator. Pick difficulty, EXP and spawn rates, death penalty and player cap, then copy a ready PalWorldSettings.ini block and Docker environment variables.",
  alternates: { canonical: "/tools/palworld-settings-generator" },
};

const faq: ToolFaq[] = [
  {
    q: "Where is PalWorldSettings.ini on a Linux server?",
    a: "On a Linux dedicated server it is Pal/Saved/Config/LinuxServer/PalWorldSettings.ini under the server install folder. Stop the server before editing it: a running server rewrites the file when it saves on shutdown and overwrites your edit.",
  },
  {
    q: "Which settings does this generator cover?",
    a: "The options Nxeon's own Palworld settings panel manages: difficulty, death penalty, player vs player, EXP rate, day and night speed, Pal spawn and capture rates, maximum guild size, player cap and Global Palbox import/export. Palworld has many more options; any key you leave out keeps the game's default.",
  },
  {
    q: "What is the Docker environment block for?",
    a: "Nxeon Palworld servers run the thijsvanloef/palworld-server-docker image, which rebuilds PalWorldSettings.ini from environment variables on every boot unless generation is switched off. If you run that image yourself, use the environment block; if you edit the ini by hand, switch generation off first (DISABLE_GENERATE_SETTINGS=True) or your edits are overwritten.",
  },
  {
    q: "What is the maximum player count?",
    a: "Palworld's dedicated server supports up to 32 players, which is also the cap this generator enforces. Plan RAM accordingly: see the server size calculator for a recommendation at your player count.",
  },
];

export default function Page() {
  return (
    <>
      <FaqJsonLd faq={faq} />
      <ToolShell
        slug="palworld-settings-generator"
        category="Server tool"
        title="Palworld Settings Generator"
        description="Choose your rates, difficulty and limits and get a PalWorldSettings.ini block plus the matching Docker environment variables. Runs in your browser."
        about={[
          {
            heading: "A safe way to build PalWorldSettings.ini",
            body: (
              <p>
                Palworld keeps all of its server rules in one long <code>OptionSettings=(...)</code> line, and one
                typo means the server ignores your changes. This generator only offers values the game accepts,
                clamps numbers to their valid range and writes the keys with the exact names the game reads.
              </p>
            ),
          },
        ]}
        steps={[
          "Pick difficulty, death penalty and the rate multipliers you want.",
          "Set your player cap (up to 32).",
          "Copy the ini block, or the Docker environment variables if you use the container image.",
          "Stop the server, apply the change, start it again.",
        ]}
        faq={faq}
        related={relatedTools("palworld-settings-generator")}
      >
        <GameConfigGeneratorTool kind="palworld" />
      </ToolShell>
    </>
  );
}
