import type { Metadata } from "next";
import { ToolShell, FaqJsonLd, type ToolFaq } from "@/components/marketing/ToolShell";
import { GameConfigGeneratorTool } from "@/components/marketing/tools/GameConfigGeneratorTool";
import { relatedTools } from "@/lib/tools/catalog";

export const metadata: Metadata = {
  title: "Valheim Server Modifiers Generator — Launch Arguments",
  description:
    "Free Valheim world modifiers generator. Choose a preset or set combat, death penalty, resources, raids and portals, and copy the exact dedicated-server launch arguments, including crossplay.",
  alternates: { canonical: "/tools/valheim-modifiers-generator" },
};

const faq: ToolFaq[] = [
  {
    q: "What is the difference between a preset and a modifier?",
    a: "A preset (-preset) sets the whole group of world rules at once. A modifier (-modifier <key> <value>) changes a single rule, such as death penalty or raids. When both are given the preset wins, so this tool warns you about modifiers a preset would override.",
  },
  {
    q: "How do I turn raids off?",
    a: "Use -modifier raids none. The other raid values are muchless, less, more and muchmore; leaving raids at Normal means no override, so nothing is emitted.",
  },
  {
    q: "How do I let Xbox and Game Pass players join?",
    a: "Add the -crossplay launch flag. Tick Crossplay above and it is included in the generated arguments.",
  },
  {
    q: "Do modifiers change an existing world?",
    a: "Modifiers are server launch settings, applied when the server starts, so restart the server after changing them. On Nxeon, the same options live in your server's Settings tab and applying them restarts the server.",
  },
  {
    q: "Are the combat and resources values official?",
    a: "Preset, death penalty, portals and raids match the values Nxeon's own Valheim settings use. The combat and resources value lists and the playerevents key come from community host documentation, so test them on a throwaway world first.",
  },
];

export default function Page() {
  return (
    <>
      <FaqJsonLd faq={faq} />
      <ToolShell
        slug="valheim-modifiers-generator"
        category="Server tool"
        title="Valheim Modifiers Generator"
        description="Pick a preset and the world modifiers you want and get the exact Valheim dedicated-server launch arguments, with crossplay if you need it."
        about={[
          {
            heading: "Valheim world modifiers, without guessing the syntax",
