/**
 * Deep link into the calculator (seo-007): `?workload=<id>&players=<n>` preselects a game and scale, so
 * a requirements page can link straight to "this game at your player count". Unknown ids are ignored;
 * the scale is clamped to the workload's own range.
 */
export function parseCalcQuery(search: string): { workloadId: string; scale: number } | null {
  const q = new URLSearchParams(search);
  const w = WORKLOADS.find((x) => x.id === q.get("workload"));
  if (!w) return null;
  const n = Math.round(Number(q.get("players")));
  const scale = Number.isFinite(n) && n > 0 ? Math.min(w.scaleMax ?? 100, n) : (w.scaleDefault ?? 10);
  return { workloadId: w.id, scale };
}
