import { PrismaClient } from "@prisma/client";
import { WORKLOADS, requirementsFor, formatRam } from "../lib/tools/server-sizing";

const DRY = process.argv.includes("--dry-run");
const NOW = new Date();
type Seed = { slug: string; title: string; excerpt: string; coverEmoji: string; tags: string[]; seoTitle: string; seoDescription: string; published: boolean; body: string };

// ── seo-016 ────────────────────────────────────────────────────────────────
const valheimMods: Seed = {
  slug: "how-to-install-mods-on-a-valheim-dedicated-server",
  title: "How to Install Mods on a Valheim Dedicated Server (Manual and One-Click)",
  excerpt: "BepInEx, Thunderstore zips, dependencies like Jotunn and reading LogOutput.log: the manual way, and the one-click way on Nxeon.",
  coverEmoji: "🛡️",
  tags: ["valheim", "mods", "bepinex", "tutorial", "dedicated server"],
  seoTitle: "How to Install Mods on a Valheim Dedicated Server (2026)",
  seoDescription: "Install Valheim mods on a dedicated server: BepInEx server type, Thunderstore zip rules, Jotunn dependencies, reading LogOutput.log, and the Nxeon one-click installer.",
  published: true,
  body: `Valheim mods load through **BepInEx**. A dedicated server has to run with BepInEx enabled before any plugin does anything, and every player who joins needs the same gameplay mods at the same version. This guide covers the manual route and the one-click route on Nxeon.

## Before you start

- **The server must be a BepInEx server, not vanilla.** On a vanilla server plugins are simply never loaded.
- **Client parity.** Gameplay mods must match on every player's PC, same versions. A mismatch shows up as "Incompatible version" or a refused join.
- **Installing a mod restarts the server.** Warn your players first.

## Manual install

1. **Switch the server type to BepInEx.** On Nxeon this is Settings, server type. Your world is kept. On the image Nxeon runs, BepInEx is downloaded and the plugins folder is synced into it on every start.
2. **Download the mod from Thunderstore.** Thunderstore downloads often bundle several versions. Extract **only the newest version**.
3. **Put each mod in its own folder** under the plugins directory: \`/opt/valheim/config/bepinex/plugins/<Author-Mod>/\`. BepInEx loads DLLs recursively. A plain DLL can also sit loose in the folder.
4. **Never extract the BepInExPack zip.** The container already has BepInEx, and a second copy breaks loading.
5. **Install dependencies yourself.** Content mods usually need library mods such as **Jotunn** (\`ValheimModding-Jotunn\`). Manual uploads do not pull dependencies in; each one needs its own folder.
6. **Restart the server** so the plugins folder is synced.

On Nxeon you can do steps 3 and 4 from the Files tab; use the extract option for zips.

## Check that it loaded: LogOutput.log

BepInEx writes a log you can read to see what actually loaded:

\`\`\`
/opt/valheim/data/bepinex/BepInEx/LogOutput.log
\`\`\`

Search it for the loading lines and compare against your plugins folder. Missing-reference or type-load exceptions almost always mean a missing dependency (Jotunn is the usual suspect) or a mod built for an older Valheim build. The server console also reports \`Game server connected\` once it is ready; with a long mod list a cold start can take about three minutes.

## One-click install on Nxeon

The **Mods & Plugins** tab installs from the NxLabs Thunderstore catalogue. For Valheim it:

- requires the BepInEx server type, and tells you to switch if you are on vanilla;
- reads the package's own declared dependency list and installs those too;
- never installs BepInExPack (the image provides BepInEx);
- refuses packages that need preloader folders (\`patchers\`, \`core\`, \`monomod\`), which the image does not sync from the config folder.

Because dependencies come from the package's own manifest, the install is the same result as the manual steps above with no missing library.

## Troubleshooting

- **Mods vanished after a Valheim update.** A game update can reset the loader. The files are intact; restart the server and check the log again.
- **Nobody can join after you added a mod.** Compare mod names and versions on the server and on the player's PC.
- **Old mod lists.** Many older lists were built for pre-1.0 builds; test them before trusting them.
- **ValheimPlus** is marked deprecated on Thunderstore after the 1.0 update and needs the matching client mod.

Ready to run one? See [Valheim server hosting](/valheim-server-hosting), or browse the [Valheim mod catalogue](/mods/games/valheim). Sizing a modded server: the [server size calculator](/tools/server-size-calculator?workload=valheim&players=10).`,
};

