  { id: "palworld", slug: "how-much-ram-does-a-palworld-server-need", name: "Palworld", route: "/palworld-server-hosting", counts: [2, 4, 8, 16, 32], emoji: "🐾" },
  { id: "rust", slug: "how-much-ram-does-a-rust-server-need", name: "Rust", route: "/rust-server-hosting", counts: [10, 25, 50, 100, 200], emoji: "🔧" },
