  { id: "enshrouded", slug: "how-much-ram-does-an-enshrouded-server-need", name: "Enshrouded", route: "/enshrouded-server-hosting", counts: [2, 4, 8, 12, 16], emoji: "🔥" },
];

function ramPost(g: (typeof RAM_GAMES)[number]): Seed {
