/**
 * seo-015: "Best <game> mods for 2026" server-side hubs, generated from the REAL NxLabs catalogue at run
 * time (nothing hand-listed, so every name, download count and loader is verifiable):
 *   active, upstream-ok, not a duplicate, declared server-compatible (serverSide required/optional),
 *   and one-click installable on Nxeon (lib/mod-install-support.ts), ranked by the source's own download count.
 * Run by the owner against the database they point DATABASE_URL at (prod):
 *   npx tsx scripts/seed-best-mods-hubs.ts --dry-run   # print the markdown only
 *   npx tsx scripts/seed-best-mods-hubs.ts             # upsert the three posts (published)
 * 7 Days to Die is deliberately absent: it has no catalogue rows (docs/MODS-COVERAGE.md), so an honest hub cannot be built yet.
 */
import { PrismaClient, Prisma } from "@prisma/client";
import { installablePairs } from "../lib/mod-quality";

type Hub = { family: string; slug: string; title: string; game: string; intro: string; emoji: string; extra?: Prisma.Sql };
const HUBS: Hub[] = [
  { family: "valheim", slug: "best-valheim-server-mods", game: "Valheim", emoji: "🛡️", title: "Best Valheim Mods for 2026 (Dedicated Server)",
    intro: "Valheim 1.0 shipped on 2026-09-09 and older mod lists were built for earlier builds, so this list is generated from the catalogue and only includes mods our installer can place on a BepInEx server. Remember players still need matching gameplay mods." },
  { family: "minecraft", slug: "best-minecraft-server-side-mods-2026", game: "Minecraft", emoji: "⛏️", title: "Best Minecraft Server-Side Mods and Plugins for 2026",
    intro: "Server-side only: plugins and mods that run on the server so players join with a normal client. Ranked by real downloads from the source.", extra: Prisma.sql`AND ("category" ILIKE ANY (ARRAY['%perform%','%admin%','%protect%','%optimi%','%utility%','%economy%','%manage%']))` },
  { family: "projectzomboid", slug: "best-project-zomboid-mods-2026-server-side", game: "Project Zomboid", emoji: "🧟", title: "Best Project Zomboid Server Mods for 2026",
    intro: "Steam Workshop mods our installer can add to a dedicated server (the server downloads them from Steam itself). Ranked by the Workshop's own subscriber counts where the catalogue has them." },
];

const db = new PrismaClient();
const fmt = (n: number | null) => (n == null ? "n/a" : n.toLocaleString("en-US"));

async function build(h: Hub) {
  const pairs = installablePairs().filter(([f]) => f === h.family);
  if (!pairs.length) return null;
  const rows = await db.$queryRaw<{ name: string; slug: string; category: string; source: string; downloads: number | null; description: string | null; loaders: string[]; authorName: string | null }[]>(Prisma.sql`
    SELECT "name","slug","category","source","downloads","description","loaders","authorName" FROM "GameMod"
    WHERE "gameFamily" = ${h.family} AND "active" AND "upstreamOk" AND "duplicateOfId" IS NULL
      AND "serverSide" IN ('required','optional') AND coalesce("downloads",0) > 0
      AND "source" IN (${Prisma.join(pairs.map(([, s]) => s))})
      ${h.extra ?? Prisma.empty}
    ORDER BY "downloads" DESC NULLS LAST LIMIT 10`);
  if (rows.length < 5) return null; // too thin to be an honest hub
  const month = new Date().toISOString().slice(0, 7);
  const list = rows.map((m, i) => `### ${i + 1}. [${m.name}](/mods/${h.family}/${m.slug})\n${m.description ? m.description.trim().slice(0, 240) + "\n\n" : ""}- Category: ${m.category}${m.authorName ? `, by ${m.authorName}` : ""}\n- Downloads at the source: ${fmt(m.downloads)}${m.loaders.length ? `\n- Loaders: ${m.loaders.join(", ")}` : ""}\n- One-click install on Nxeon: yes`).join("\n\n");
  return {
    slug: h.slug, title: h.title, coverEmoji: h.emoji, tags: [h.game.toLowerCase(), "mods", "best mods", "2026"],
    excerpt: `The ${rows.length} most-downloaded server-compatible ${h.game} mods you can install in one click, from our live catalogue (${month}).`,
    seoTitle: `${h.title.replace(/ \(.*\)/, "")} | Nxeon`, seoDescription: `Top ${h.game} server-side mods for 2026 by real download counts, each installable in one click on a Nxeon server.`,
    body: `${h.intro}\n\n_Generated from the NxLabs catalogue in ${month}. Download counts are the source's own._\n\n${list}\n\n## How to install\n\nOpen your server's **Mods & Plugins** tab and install any of these in one click; dependencies are added automatically. Browse the full catalogue: [${h.game} mods](/mods/games/${h.family}). Need a server? See [${h.game} server hosting](/${h.family === "projectzomboid" ? "project-zomboid" : h.family}-server-hosting).`,
  };
}

(async () => {
  const dry = process.argv.includes("--dry-run");
  for (const h of HUBS) {
    const p = await build(h);
    if (!p) { console.log(`skip ${h.slug}: no honest list available`); continue; }
    if (dry) { console.log(`--- ${p.slug}\n${p.body}\n`); continue; }
    const data = { title: p.title, excerpt: p.excerpt, body: p.body, coverEmoji: p.coverEmoji, tags: p.tags, seoTitle: p.seoTitle, seoDescription: p.seoDescription, published: true, publishedAt: new Date() };
    await db.blogPost.upsert({ where: { slug: p.slug }, create: { slug: p.slug, ...data }, update: data });
    console.log("upserted", p.slug);
  }
  await db.$disconnect();
})();
